mapper.select:
SELECT c.id, c.club_id, c.user_id, su.nickname AS requester_nickname, c.status, c.reason, c.planned_time, c.planned_location, c.content, c.submitted_at, c.deadline, c.created_at, c.updated_at, EXISTS(SELECT 1 FROM concept_vote v WHERE v.concept_id = c.id AND v.voter_id = #{userId} AND v.round = CASE WHEN c.status = 3 THEN 2 ELSE 1 END) AS my_voted FROM concept_session c JOIN sys_user su ON su.id = c.user_id WHERE c.club_id = #{clubId}
AND c.status = #{status}
ORDER BY c.created_at DESC
